def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = str(value).strip()
        if "<" in value and ">" in value:
            value = value.split("<", 1)[1].split(">", 1)[0]
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return value

    def normalize_phone(value):
        value = str(value)
        markers = [m.start() for m in re.finditer(r"x|ext|#", value, flags=re.IGNORECASE)]
        if markers:
            value = value[:min(markers)]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = str(value).strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = str(value).strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = str(value)
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def opted_out(value):
        return str(value).strip().lower() in {"y", "yes", "true", "1"}

    people = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        people.append({
            "index": index,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "source": str(row["source"]).strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", str(row["tags"]))
                if tag.strip()
            },
            "opted_out": opted_out(row["opted_out"]),
        })

    parent = list(range(len(people)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}

    for i, person in enumerate(people):
        email = person["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        phone = person["phone"]
        last_name = person["last_name"]
        if phone and last_name:
            key = (phone, last_name.casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, person in enumerate(people):
        groups.setdefault(find(i), []).append(person)

    def best_value(group, field):
        candidates = [p for p in group if p[field]]
        if not candidates:
            return ""
        candidates.sort(key=lambda p: (
            p["source"] != "manual",
            -p["updated_dt"].timestamp(),
            p["index"],
        ))
        return candidates[0][field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(p["index"] for p in g)):
        latest = max(p["updated_dt"] for p in group)
        output.append({
            "first_name": best_value(group, "first_name"),
            "last_name": best_value(group, "last_name"),
            "zip": best_value(group, "zip"),
            "email": best_value(group, "email"),
            "phone": best_value(group, "phone"),
            "source": best_value(group, "source"),
            "tags": ";".join(sorted(set().union(*(p["tags"] for p in group)))),
            "opted_out": "Y" if any(p["opted_out"] for p in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
